question.en:
What does the Command pattern give you that passing a plain callback does not?
```ts
interface Command {
  execute(): void;
  undo(): void;
}

class AddLine implements Command {
  constructor(private doc: string[], private line: string) {}
  execute() { this.doc.push(this.line); }
  undo() { this.doc.pop(); }
}

const history: Command[] = [];

function run(command: Command) {
  command.execute();
  history.push(command);
}
```

